{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已完成任务的项目工时总和排名",
      "business_question": "按项目汇总状态为“已完成”的任务的工时总和，并降序排列取前两名。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标，缺失该任务无法支持关于高工时项目的决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "top_n",
          "params": {
            "field": "total_hours",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
